import{categorySubject}from"./category-subject.js";const renderCategories=(e,t=document)=>{const o=t.querySelector(".blog__categories-list");o&&(o.innerHTML=e.map(e=>`\n        <button class="blog__category" data-category="${e.name}">\n            <div class="blog__category-info">\n                <strong>${e.name}</strong>\n            </div>\n        </button>`).join("\n"),o.querySelectorAll(".blog__category").forEach(e=>{e.addEventListener("click",()=>{categorySubject.notifyObservers(e.dataset.category)})}))};export const initCategories=async(e=document)=>{const t=e.querySelector(".blog__categories-button"),o=e.querySelector(".blog__categories-list");if(!t||!o)return;let n=null;o.style.display="none",t.addEventListener("click",async()=>{if(!n){const t=await fetch("/data/categories.json");n=await t.json(),renderCategories(n,e)}o.style.display="none"===o.style.display?"flex":"none"})};